-- Assigned staff/admin see private notes; the unassigned queue exposes only public transcript.
grant create on schema api to git_tutor_commands;
create or replace function api.get_conversation(p_conversation_id uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor(true);result jsonb;messages jsonb;notes jsonb;begin
 if not exists(select 1 from app_private.conversations where id=p_conversation_id and(account_id=actor or owner_account_id=actor or app_private.has_role(actor,'admin')or(state='waiting'and owner_account_id is null and app_private.support_staff(actor))))then raise exception'FORBIDDEN';end if;result:=app_private.support_summary(actor,p_conversation_id);select coalesce(jsonb_agg(x.item order by x.sequence),'[]'::jsonb)into messages from(select m.sequence,jsonb_build_object('message_id',m.id,'author',m.author,'text',m.text,'created_at',m.created_at,'delivery_state',d.state)item from app_private.support_messages m join app_private.support_message_delivery d on d.message_id=m.id where m.conversation_id=p_conversation_id order by m.sequence desc limit 100)x;
 result:=result||jsonb_build_object('messages',messages,'earlier_messages_available',(select count(*)>100 from app_private.support_messages where conversation_id=p_conversation_id));
 if app_private.has_role(actor,'admin')or exists(select 1 from app_private.conversations where id=p_conversation_id and owner_account_id=actor)then select coalesce(jsonb_agg(jsonb_build_object('note_id',n.id,'text',n.text,'created_at',n.created_at)order by n.created_at,n.id),'[]'::jsonb)into notes from app_private.support_notes n where n.conversation_id=p_conversation_id;result:=result||jsonb_build_object('private_notes',notes);end if;return result;end$$;
revoke create on schema api from git_tutor_commands;
